    tzm: 'ⵉⵙ ⴰⵔ ⴰⴷ ⴰⵏⵏⴰⵢ ⵓⵙⵙⵏⵓⵙ ⴰⵎⵙⵙⵏⵉ ⵏ ⵜⵉⵎⵙⵙⵉⵔⵜ ⵏⵏⵖ ⴰⴷ ⵉⵙⵙⵏⵓⵙ ⵙⵜⴰⵡⵔⴰ ⵙⵜⵉⵎⵙⵙⵉⵔⵜ ⵏⵏⵖ؟',
