  contentEn: `
# Will Artificial Intelligence Help Us or Start Thinking for Us?

Artificial intelligence has become present in many details of our daily lives. We use it for research, learning, programming, writing, and analyzing information. We can also ask it to explain a complex idea or help us understand a subject we have never studied before.

But with this rapid expansion comes an important question:

**Are we using artificial intelligence to become more capable, or could we reach a point where we let it think instead of us?**

This question is not only about technology. It is also about our relationship with knowledge itself.

## The problem is not artificial intelligence alone

It is easy to say that artificial intelligence will make people think less, but the situation is more complicated.

The tool itself is not always the problem. The way we use it can make the difference.

If we use artificial intelligence simply to obtain a final answer without understanding anything, we may get a fast result, but we have not necessarily gained real knowledge.

However, if we ask it to explain an idea, provide the studies it relies on, identify its sources, compare different interpretations, and then analyze and verify the information ourselves, artificial intelligence can become a learning tool rather than a replacement for thinking.

This difference may seem simple, but it is fundamental.

## Can excessive reliance weaken our thinking?

Researchers have already started studying this question.

A study published in 2025 on the use of generative artificial intelligence tools found a relationship between reliance on these tools and reduced forms of cognitive engagement, particularly when people use the tool to obtain answers instead of participating themselves in the thinking process.

The study also found that confidence in one's own ability to perform a task can influence the amount of mental effort a person invests.

This raises an important concern:

**The easier an answer becomes to obtain, the more tempting it may become to skip the process that leads to it.**

This does not mean that artificial intelligence will make everyone less intelligent, nor does it mean that using it will inevitably reduce our ability to think.

But it is reasonable to ask:

**What happens when the answer becomes easier than the question?**

## When thinking itself becomes something we can delegate

Thinking is not simply reaching a conclusion.

When we research a subject, read, compare, make mistakes, review our ideas, and finally reach a conclusion, we do not only obtain information.

We build a capability.

We learn how to search.

How to distinguish a strong source from a weak one.

How to identify contradictions.

How to ask better questions.

And how to change our minds when stronger evidence appears.

If we start asking artificial intelligence to perform all these stages on our behalf, we may obtain the result, but we may lose part of the process that made us capable of reaching the result ourselves.

Therefore, the real question is not:

**Does artificial intelligence think?**

It is:

**Are we still thinking when we use it?**

## But rejecting artificial intelligence is not a solution either

There is another mistake we can make: becoming so afraid of technology that we reject it.

Technology does not stop because we are afraid of it.

Artificial intelligence is developing rapidly, and it is difficult to imagine that ignoring it will make the world stop using it.

In fact, not learning how to use it can become a problem in itself.

A student who knows how to use artificial intelligence for research, learning, and analysis may be more capable of completing certain tasks than someone who refuses to use it completely.

But the important difference is that the first person uses the tool without allowing it to become a replacement for their own mind.

## A lesson from the history of technology

The history of technology contains many examples of companies that struggled to adapt to major technological changes.

One famous example is Nokia. It was once one of the strongest mobile phone companies in the world, but it faced major difficulties during the transition to the smartphone era, while other companies were building new systems and ecosystems around smartphones.

The lesson is not that every company that rejects technology will inevitably collapse, nor that adapting to technology guarantees success.

But it illustrates something important:

**Major technological transformations do not wait for institutions that refuse to adapt.**

The same idea can apply to individuals.

The solution is not to say:

"I will not use artificial intelligence."

The solution is to learn:

**How can I use it in a way that makes me stronger rather than more dependent?**

## Artificial intelligence as an assistant teacher

The best way to use artificial intelligence is to treat it as an assistant teacher, not as a mind that replaces our own.

We can ask it:

Explain this concept.

Give me scientific studies about it.

List the sources.

Compare the findings.

Explain how the researchers reached this conclusion.

Give me an example.

Then we ask our own questions, review the sources, and try to build our own understanding.

In this way, artificial intelligence does not become the thing that thinks instead of us.

It helps us think more broadly.

## But there is another problem: mistakes

There is something we should never forget.

Artificial intelligence can make mistakes.

It can provide incorrect information, misunderstand a question, provide an unsuitable source, or mix accurate information with inaccurate information.

For this reason, complete reliance on it can be dangerous, especially when dealing with scientific, medical, legal, or historical information.

Even artificial intelligence tools themselves warn users that errors are possible.

Therefore, when information matters, it is not enough to say:

**"Artificial intelligence said it."**

We should ask:

Where is the source?

Is the source reliable?

Does the study actually say what was claimed?

Are there other studies that disagree?

This is where human thinking returns to its natural place.

## The solution is neither rejection nor complete dependence

There are two extremes.

The first is:

**Rejecting artificial intelligence completely.**

The second is:

**Giving everything to it.**

The better option is a third path:

**Conscious and moderate use.**

We use it when it can help us.

We ask it to explain.

We ask it to suggest sources.

We ask it to help us identify mistakes.

But we keep the final decision for ourselves.

We read.

We verify.

We analyze.

And we decide.

## In the end

I do not think the right question is:

**Is artificial intelligence good or bad?**

The more important question is:

**What are we doing with it?**

Artificial intelligence can become a tool that makes people more capable of learning, researching, and creating.

But if we use it incorrectly, it can make us accustomed to receiving answers without making the effort to understand them.

That is why I do not want to live away from artificial intelligence.

At the same time, I do not want to live completely dependent on it.

I want to learn from it, not stop learning because of it.

I want it to help me reach studies and information, not prevent me from reading the sources.

I want it to explain things to me, not eliminate my ability to understand.

And I want to use its capabilities as much as possible while always keeping the ability to say:

**This answer may be wrong. Let us verify it.**

Because the future will not necessarily belong to those who use artificial intelligence the most.

It may belong to those who know **how to use it without losing their ability to think for themselves.**

## Scientific References

[1] Lee, H., & others (2025). The impact of generative AI on critical thinking and cognitive engagement.

[2] Microsoft Research & Carnegie Mellon University (2025). The Impact of Generative AI on Critical Thinking: Self-Reported Reductions in Cognitive Effort and Confidence Effects.

[3] Kasneci, E., et al. (2023). ChatGPT for good? On opportunities and challenges of large language models for education. Learning and Individual Differences, 103, 102274.

[4] UNESCO (2023). Guidance for Generative AI in Education and Research.

[5] Dwivedi, Y. K., et al. (2023). So what if ChatGPT wrote it? Multidisciplinary perspectives on opportunities, challenges and implications of generative conversational AI for research, practice and policy. International Journal of Information Management, 71, 102642.
`
