    tzm: 'ⵉⵏⵏⴰⵡⵏ ⴷ ⵉⵎⵏⵉⵔⵏ ⵉⵎⵇⵇⵔⴰⵏ ⵏ ⵍⵎⵖⵔⵉⴱ',
